BEGIN;
UPDATE entities SET name = 'Caspian Sea', type = 'place', aliases = ARRAY['the Caspian', 'Caspian group']::text[], description = 'A large inland sea, at one time expanded, that blocked the northward journeys of the Adamites; later Andites entered Europe by the Caspian Sea route. On April 1, A.D. 24, Jesus left Nazareth as conductor of a caravan to the southeastern Caspian Sea region and returned a full year later.' WHERE id = 'caspian-sea';
UPDATE entities SET name = 'Center of Centers', type = 'place', aliases = NULL, description = 'A name for the center of all things at Paradise. The superuniverses swing in their space path opposite the Center of Centers, and the Infinite Spirit is approachable at the center of centers.' WHERE id = 'center-of-centers';
UPDATE entities SET name = 'Chicago', type = 'place', aliases = NULL, description = 'The U.S. city that the papers use to show the energy value of sunlight: Chicago''s bill for sunshine would amount to considerably over 100 million dollars a day.' WHERE id = 'chicago';
UPDATE entities SET name = 'Cincinnati Island', type = 'place', aliases = NULL, description = 'A land area named once in the papers: during the Devonian period the land southeast of the Cincinnati Island stayed well above water, while very much of western Europe, including the British Isles, was submerged.' WHERE id = 'cincinnati-island';
UPDATE entities SET name = 'Connecticut', type = 'place', aliases = ARRAY['eastern-Connecticut']::text[], description = 'Named in the papers only in ''the great eastern-Connecticut fault'', which appeared in North America during the early reptilian age; one side eventually sank two miles.' WHERE id = 'connecticut';
UPDATE entities SET name = 'Daphne', type = 'place', aliases = NULL, description = 'The grove of Daphne at Antioch, a notorious shrine. Gonod and Ganid visited it, but Jesus declined to go with them.' WHERE id = 'daphne';
UPDATE entities SET name = 'enemy', type = 'being', aliases = ARRAY['the enemy of the kingdom']::text[], description = 'In Jesus'' phrase ''the enemy of the kingdom'', used when he warned the apostles that this enemy would seek to draw them away. The paragraph does not name the enemy.' WHERE id = 'enemy';
UPDATE entities SET name = 'Ezraeon', type = 'being', aliases = NULL, description = 'Ezraeon was a friend of Joseph and Mary who owned the boat that carried them from Alexandria to Joppa in August of 4 B.C. as they returned from Egypt.' WHERE id = 'ezraeon';
UPDATE entities SET name = 'Galantia', type = 'being', aliases = NULL, description = 'The associate of Gavalia, head of the Brilliant Evening Stars of Nebadon, and the first of the ascendant superangels to attain this high estate. Galantia maintains headquarters on Jerusem as the associate head of these superangels.' WHERE id = 'galantia';
UPDATE entities SET name = 'Gilead', type = 'place', aliases = NULL, description = 'One of the cities and towns of Perea where the seventy worked during the Perean mission that began on January 3, A.D. 30. The papers also name Gilead as one of the reputed tribes that dwelt east of the Jordan.' WHERE id = 'gilead';
UPDATE entities SET name = 'isolation worlds', type = 'place', aliases = NULL, description = 'The satellites around the Father''s world of Jerusem, which in Satania serve as detention spheres; the few seraphim and cherubim who joined the Satania rebellion are confined on these isolation worlds.' WHERE id = 'isolation-worlds';
UPDATE entities SET name = 'Jah', type = 'being', aliases = NULL, description = 'One of the sundry names that the Semites used for their Deity, because they disliked to speak the name of their Deity.' WHERE id = 'jah';
UPDATE entities SET name = 'Karkar', type = 'place', aliases = NULL, description = 'The site of a battle where King Ahab of Ephraim and ten allied groups fought against Assyrian King Shalmaneser III, resulting in a draw that stopped the Assyrian advance but decimated the allies.' WHERE id = 'karbar';
UPDATE entities SET name = 'Methuselah', type = 'being', aliases = NULL, description = 'The papers do not use this name. They tell of records of a man who lived over nine hundred ''years'', a span that represents not quite seventy years and comes from the confusion of the twenty-eight-day month with the later year.' WHERE id = 'methuselah';
UPDATE entities SET name = 'leader of the Mithraic cult', type = 'being', aliases = NULL, description = 'A leader of the Mithraic cult whom Jesus met in Corinth. Jesus told him that the mystery of eternal salvation dwells within his own soul, not in man-made mysteries and human philosophies.' WHERE id = 'mithraic-priest-in-corinth';
UPDATE entities SET name = 'Mother Eves', type = 'being', aliases = NULL, description = 'The Material Daughters chosen by a Melchizedek life carrier, from volunteers who answer the call of the System Sovereign, to mate with him on a system midsonite world. Their offspring are the midsoniters.' WHERE id = 'mother-eves';
UPDATE entities SET name = 'Nabu', type = 'being', aliases = NULL, description = 'One of the seven chief deities of Mesopotamia to which the Salem teachers reduced the gods: Bel, Shamash, Nabu, Anu, Ea, Marduk, and Sin.' WHERE id = 'nabu';
UPDATE entities SET name = 'Nambia', type = 'being', aliases = NULL, description = 'Nambia is the original and first-born Life Carrier of Nebadon, serving as one of the life-determining trio along with Gabriel and the Father Melchizedek who direct the corps of one hundred million Life Carriers in the universe.' WHERE id = 'nambia';
UPDATE entities SET name = 'Nebadon Revelatory Corps', type = 'order', aliases = NULL, description = 'The body at whose request a Mighty Messenger presented the paper on Universal Unity. That paper closes the series of twenty-five papers by various authors that a commission of twelve Nebadon personalities, under the direction of Mantutia Melchizedek, sponsored and put into English in 1934.' WHERE id = 'nebadon-revelatory-corps';
UPDATE entities SET name = 'Paradise Source and Center', type = 'place', aliases = NULL, description = 'The eternal Isle of Paradise as one of the Seven Absolutes of Infinity: the second nondeity pattern, the absolute of patterns, and the foundation of gravity control throughout the universes. 19:1.12 also speaks of the divine Paradise Source and Center of all personality reality and all cosmic existence.' WHERE id = 'paradise-source-and-center';
UPDATE entities SET name = 'Pella', type = 'place', aliases = NULL, description = 'A place by the Jordan near which Jesus was baptized and John the Baptist''s company camped. Later Jesus made his last headquarters at the Pella camp in Perea, where more than twelve hundred persons gathered; Isador wrote the Gospel according to Matthew at Pella after he escaped from Jerusalem in A.D. 70.' WHERE id = 'pella';
UPDATE entities SET name = 'Roman Catholic Church', type = 'religion', aliases = NULL, description = 'The papers do not use this name. They describe the state church of the Roman Empire, which became institutionalized nearly to the point of spiritual barrenness, and the later totalitarian ecclesiastical domination from which the secular revolt freed Western peoples.' WHERE id = 'roman-catholic-church';
UPDATE entities SET name = 'Sarepta', type = 'place', aliases = NULL, description = 'A location in Phoenicia through which Jesus and the apostles passed during their journey from Sidon to Tyre in July of the year 29 CE.' WHERE id = 'sarepta';
UPDATE entities SET name = 'Simon of Bethpage', type = 'being', aliases = ARRAY['Simon']::text[], description = 'A man of Bethpage at whose home Thomas stayed alone for about a week after the crucifixion, until Peter and John went to Bethpage and brought him back to the apostles.' WHERE id = 'simon-of-bethphage';
UPDATE entities SET name = 'Sudna', type = 'being', aliases = NULL, description = 'A servital of Havona who came over from the superuniverse service, was received on Paradise, knew the Father, entered the divine embrace, and is not.' WHERE id = 'sudna';
UPDATE entities SET name = 'Thaddeus', type = 'being', aliases = NULL, description = 'A name of one of the Alpheus twins: ''James and Judas, who were also called Thaddeus and Lebbeus''. Thaddeus handed Jesus the cup at the Last Supper.' WHERE id = 'thaddeus';
UPDATE entities SET name = 'Thamna', type = 'place', aliases = NULL, description = 'A village whose citizens, with citizens of Arimathea, came to Bethel at the end of June, A.D. 27, to invite Jesus to visit their villages.' WHERE id = 'thamna';
UPDATE entities SET name = 'Universal Mind', type = 'concept', aliases = NULL, description = 'The mind of the universes, of which the Conjoint Actor (the Infinite Spirit) is the source; the Infinite Spirit is called a universal mind and controls the universal mind circuit. The papers also use the term for the Universal Mind with which the Stoics sought harmony.' WHERE id = 'universal-mind';
UPDATE entities SET name = 'Universal Mother', type = 'being', aliases = NULL, description = 'A name that the papers give to two Deity persons: the Eternal Son, who is the Universal Mother in the same sense that God is the Universal Father, and the Supreme Being, the Universal Mother of whose cosmic reaction the morontia soul is the child.' WHERE id = 'universal-mother';
UPDATE entities SET name = 'Urantia Papers', type = 'concept', aliases = ARRAY['accompanying papers', 'those papers', 'these papers', 'These papers', 'the series', 'papers', 'narratives', 'paper', 'narrative']::text[], description = 'The papers that constitute the most recent presentation of truth to the mortals of Urantia; a composite presentation by many beings, not the work of a single universe personality.' WHERE id = 'urantia-papers';
UPDATE entities SET name = 'Vosges mountains', type = 'place', aliases = ARRAY['Vosges']::text[], description = 'Mountains whose beginning, along with the Black Forest and Ural mountains, the papers place in the Carboniferous period.' WHERE id = 'vosges-mountains';
UPDATE entities SET name = 'Wisdom of Solomon', type = 'concept', aliases = NULL, description = 'A book in which the penetration of both Platonic philosophy and Stoic doctrines into Hellenized Jewish belief is exhibited. The papers quote from it the passage that ''the race is not to the swift, nor the battle to the strong ... but fate and chance befall them all.''' WHERE id = 'wisdom-of-solomon';
UPDATE entities SET name = 'Palm Sunday', type = 'concept', aliases = ARRAY['that Sunday']::text[], description = 'The papers do not use this name. It labels the Sunday on which Jesus rode a colt from Bethany into Jerusalem in a public entry, while a multitude from the city met him waving palm branches and shouting hosannas.' WHERE id = 'palm-sunday';
UPDATE entities SET name = 'Philip (Tetrarch)', type = 'being', aliases = NULL, description = 'Philip the Tetrarch, brother of Herod Antipas, whose domain had Caesarea-Philippi as its capital. He became a halfhearted believer in Jesus and sent word that the Master was free to live and work in his domains.' WHERE id = 'philip-tetrarch';
UPDATE entities SET name = '1-2-3 the First', type = 'being', aliases = NULL, description = 'The eldest of the primary midwayers, leader of the loyal midway creatures in the service of Gabriel at the Caligastia betrayal; his fearless leadership helped reduce the casualties in his order. He serves on Jerusem as one of the twenty-four counselors and once functioned as governor general of Urantia after Pentecost.' WHERE id = '1-2-3-the-first';
UPDATE entities SET aliases = ARRAY['Archelaus']::text[] WHERE id = 'herod-archelaus';
UPDATE entities SET aliases = ARRAY['Elijah', 'Mark, Elijah']::text[] WHERE id = 'elijah-mark';
UPDATE entities SET aliases = ARRAY['John', 'strange preacher']::text[] WHERE id = 'john-the-baptist';
UPDATE entities SET aliases = ARRAY['Urantia Brotherhood of Urantia Midwayers']::text[] WHERE id = 'united-midwayers-of-urantia';
UPDATE entities SET aliases = ARRAY['Uzziah']::text[] WHERE id = 'azariah';
UPDATE entities SET aliases = ARRAY['John', 'Zebedee, John']::text[] WHERE id = 'john-zebedee';
UPDATE entities SET aliases = ARRAY['Mortal Corps of Finality', 'Mortal Corps of the Finality', 'Corps of the Mortal Finality', 'Mortal Corps of Finaliters', 'Corps of the Finality', 'Mortal Finaliter Corps']::text[] WHERE id = 'corps-of-mortal-finaliters';
